def evaluate(input_data):
    """Evaluate Forth source lines and return the resulting integer stack."""
    stack = []
    words = {word: (word,) for word in ("+", "-", "*", "/", "dup", "drop", "swap", "over")}
    tokens = iter(" ".join(input_data).lower().split())

    def is_number(token):
        return token.isascii() and token.isdigit()

    def resolve(token):
        if is_number(token):
            return (int(token),)
        if token not in words:
            raise ValueError(f"undefined operation: {token}")
        return words[token]

    def execute(instructions):
        for instruction in instructions:
            if isinstance(instruction, int):
                stack.append(instruction)
                continue

            required = 1 if instruction in ("dup", "drop") else 2
            if len(stack) < required:
                raise StackUnderflowError(
                    f"Insufficient number of items in stack: {instruction} requires {required}"
                )

            if instruction == "dup":
                stack.append(stack[-1])
            elif instruction == "drop":
                stack.pop()
            elif instruction == "swap":
                stack[-2], stack[-1] = stack[-1], stack[-2]
            elif instruction == "over":
                stack.append(stack[-2])
            else:
                left, right = stack[-2:]
                if instruction == "+":
                    result = left + right
                elif instruction == "-":
                    result = left - right
                elif instruction == "*":
                    result = left * right
                else:
                    if right == 0:
                        raise ZeroDivisionError("divide by zero")
                    # Truncate toward zero without converting large integers to floats.
                    result = abs(left) // abs(right)
                    if (left < 0) != (right < 0):
                        result = -result
                stack[-2:] = [result]

    for token in tokens:
        if token != ":":
            execute(resolve(token))
            continue

        name = next(tokens, None)
        if name is None or is_number(name) or name in (":", ";"):
            raise ValueError("invalid word definition: expected a non-numeric word name")

        definition = []
        for token in tokens:
            if token == ";":
                break
            if token == ":":
                raise ValueError("invalid word definition: nested definitions are not supported")
            # Bind existing meanings now, so later redefinitions do not affect this word.
            definition.extend(resolve(token))
        else:
            raise ValueError("invalid word definition: missing terminating semicolon")
        words[name] = tuple(definition)

    return stack
